"""Batch 06 - California cities and counties (Claude manual research, Nov 2026).

Most California registries date from 2008-2010 "Abandoned Residential Property Registration" ordinances: the
beneficiary/trustee must register a vacant property in default, usually within 10 days of an inspection finding it
vacant, keep a local property manager, and pay an annual fee set by council resolution.
"""
from helpers import rule, save

CA_COUNTY = "California county ordinances apply only in unincorporated territory."
FEE_RES = "Annual fee set by City Council resolution (amount not confirmed)."
CA_DOCS = ["City registration form", "Beneficiary and trustee names and street addresses (no P.O. boxes)",
           "Local property management company / agent contact (24-hour)", "Property address / APN",
           "Date the property became vacant / Notice of Default information", "Annual registration fee"]
CA_OTHER = ["Inspect the property regularly while vacant", "Secure and maintain the property (landscaping, pools, entry points)",
            "Post contact information for the local property manager on the property", "Notify the city of changes and de-register when sold or occupied"]


def ca_yes(name, display, ordinance, url, fee=FEE_RES, trigger="Residential property in default/foreclosure that is found vacant (abandoned).",
           deadline="Within 10 days of the inspection finding the property vacant.", vacant="Yes", foreclosure="Yes",
           confidence="Medium", reason="Ordinance chapter confirmed in code index/search; full text not readable.", sources=None, **kw):
    return rule("city", "CA", name, display, vacant, foreclosure,
                registration_trigger=trigger, who_must_register=kw.pop("who", "Beneficiary and trustee (lender/servicer)."),
                registration_deadline=deadline, ordinance_name=ordinance, ordinance_url=url,
                registration_method=kw.pop("method", "Mail"), registration_fee=fee,
                renewal_frequency=kw.pop("renewal", "Annual while vacant / in default"),
                documents_required=kw.pop("docs", CA_DOCS), other_requirements=kw.pop("other", CA_OTHER),
                summary=kw.pop("summary", f"{display} requires registration of vacant/abandoned residential properties in default ({ordinance}); fee: {fee}"),
                confidence=confidence, confidence_reason=reason, source_urls=sources or [url], **kw)


def ca_unclear(name, display, note="No registration ordinance was found in searches; many nearby California cities have one, so verify in the city code."):
    return rule("city", "CA", name, display, "Unclear", "Unclear", summary=f"{display}: {note}",
                confidence="Low", confidence_reason="City code not readable; no program found.",
                source_urls=["https://blog.safeguardproperties.com/vpr-ordinance-california-wisconin"])


